package com.worksphere.service;
import com.worksphere.dto.rating.*; import com.worksphere.entity.*; import com.worksphere.repository.*; import com.worksphere.exception.*; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Service; import java.util.*;
@Service public class RatingService {private final RatingRepository ratings;private final CommitmentRepository commitments;private final UserService users;private final WorkerProfileRepository workers;private final EmployerProfileRepository employers;public RatingService(RatingRepository r,CommitmentRepository c,UserService u,WorkerProfileRepository w,EmployerProfileRepository e){ratings=r;commitments=c;users=u;workers=w;employers=e;} public Rating rate(Authentication a,RatingRequest r){User from=users.current(a);Commitment c=commitments.findById(r.commitmentId()).orElseThrow();if(c.status!=CommitmentStatus.COMPLETED)throw new BadRequestException("Job must be completed before rating");if(!((c.worker.id.equals(from.id)&&c.employer.id.equals(r.toUserId()))||(c.employer.id.equals(from.id)&&c.worker.id.equals(r.toUserId()))))throw new UnauthorizedActionException("You cannot rate this user");if(r.rating()<1||r.rating()>5)throw new BadRequestException("Rating must be 1-5");if(ratings.findByCommitmentIdAndFromUserIdAndToUserId(c.id,from.id,r.toUserId()).isPresent())throw new BadRequestException("Already rated");Rating x=new Rating();x.commitment=c;x.fromUser=from;x.toUser=users.byId(r.toUserId());x.rating=r.rating();x.review=r.review();x=ratings.save(x);updateTarget(x.toUser);return x;} public List<Rating> forUser(Long id){return ratings.findByToUserIdOrderByCreatedAtDesc(id);} private void updateTarget(User u){List<Rating> rs=ratings.findByToUserIdOrderByCreatedAtDesc(u.id);double avg=rs.stream().mapToInt(x->x.rating).average().orElse(0);if(u.role==Role.JOB_SEEKER){var p=workers.findByUserId(u.id).orElse(null);if(p!=null){p.rating=avg;p.ratingCount=rs.size();workers.save(p);}}else if(u.role==Role.EMPLOYER){var p=employers.findByUserId(u.id).orElse(null);if(p!=null){p.rating=avg;p.ratingCount=rs.size();employers.save(p);}}} }
